#include <stdio.h>
#include <string.h>
void copy_bounded(char *dst, size_t cap, const char *src) {
    if (cap == 0) return;
    size_t n = 0;
    while (n + 1 < cap && src[n] != '\0') {
        dst[n] = src[n];
        n++;
    }
    dst[n] = '\0';
}
int main(void) {
    char buf[4];
    copy_bounded(buf, sizeof buf, "hello");
    printf("%s\n", buf);
    return strcmp(buf, "hel") == 0 ? 0 : 1;
}

