int cmp_int(const void *left, const void *right) {
    int a = *(const int *)left;
    int b = *(const int *)right;
    return (a > b) - (a < b);
}
int main(void) {
    int a[] = {3, 1, 2};
    qsort(a, 3, sizeof *a, cmp_int);
    printf("%d %d %d\n", a[0], a[1], a[2]);
    return a[0] == 1 && a[1] == 2 && a[2] == 3 ? 0 : 1;
}

